      "granularity_name": "other"
    },
    {
      "chord_quality": "sus4",
      "function_role": "inversion-label-consistency",
      "narrative": "Chapter 2 (p. 4) extends the sus4 naming convention to all inversions: 'Of course, this applies to all of the inversions as well'. No inversion should revert to C2 or add-2 notation.",
