    {
      "chord_quality": "3-part",
      "function_role": "playability-priority-over-4-part",
      "narrative": "Chapter 7 (p. 71) prescribes that 3-part chords take priority over 4-part as the foundational chord literacy on ergonomic grounds: 'As guitarists, we can see that 3-part chords are easier to play than 4-part chords.' The 840-chord catalog (Chapters 6-9) introduces 3-part material before 4-part.",
      "source_principle_ids": [
        "three-part-before-four-part"
      ],
      "source_work_id": "almanac-vol-4",
